COPY public.ai_compliance_checklists (id, dsr_id, validated_by, validated_at, checklist_json, status) FROM stdin;
b6113743-ae21-4fda-8fd5-896d08d429ea	4a6f596c-dcef-437c-bfa1-c777e0db5e6c	\N	2026-01-27 14:00:00+00	{"B_i": {"answer": "Yes", "remarks": "Contains personal financial transaction data classified as sensitive under UU PDP."}, "B_v": {"answer": "Yes", "remarks": "Research consent included in digital banking app consent form signed by customers."}, "D_i": {"answer": "Yes", "remarks": "Generative AI models are used for customer financial insight generation. AI Checklist Assessment completed separately."}, "B_ii": {"answer": "Yes", "remarks": "PII fields are masked and tokenised before sharing; access restricted to authorised team members only."}, "B_iv": {"answer": "Yes", "remarks": "Customer consent obtained via Terms & Conditions agreement at account opening."}, "B_vi": {"answer": "Yes", "remarks": "Data is processed within the BU secured analytics environment with role-based access control enforced."}, "A_i_1": {"answer": "No", "remarks": "No revenue cannibalization risk; data is used solely for internal AI model development."}, "A_i_2": {"answer": "No", "remarks": "Data is anonymised prior to use; no direct customer relationship impact."}, "A_i_3": {"answer": "No", "remarks": "No other commercial interests identified."}, "B_iii": {"answer": "Yes", "remarks": "Transaction records contain customer identifiers and financial data constituting personal data."}, "C_i_1": {"answer": "No", "remarks": "Compliant with OJK regulations on data usage for financial analytics purposes."}, "C_i_2": {"answer": "No", "remarks": "Compliant with UU PDP (Personal Data Protection Law No. 27/2022)."}, "C_i_3": {"answer": "No", "remarks": "Compliant with internal Data Governance Policy v2.1 and AI Ethics Guidelines."}, "A_ii_1": {"answer": "No", "remarks": "No confidential partnership data is included in the transaction dataset."}, "A_ii_2": {"answer": "No", "remarks": "No patent information present in scope of data."}, "A_ii_3": {"answer": "No", "remarks": "No M&A-related information included."}, "A_ii_4": {"answer": "No", "remarks": "No other commercial secrets identified in the dataset."}, "sign_off": {"remarks": "All compliance requirements have been reviewed and satisfied. Data sharing approved for AI model development purposes.", "approved": "Yes", "prepared_by": "Rendra Kusuma Wijaya", "prepared_date": "2026-01-25", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "2026-01-25", "prepared_position": "Head of Digital Innovation", "prepared_signature": "data:image/png;base64,", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": "data:image/png;base64,"}, "ai_assessment": {"items": {"input_1": {"status": "Yes", "remarks": "Customer transaction data is fully anonymised and tokenised before being used as AI model input. No raw PII — names, account numbers, phone numbers — is included in any prompt or model input."}, "input_2": {"status": "Yes", "remarks": "All data inputs to the Gen AI pipeline are pseudonymised. Customer identifiers are replaced with internal tokens, and synthetic dummy data is used during model exploration and testing phases."}, "input_3": {"status": "Yes", "remarks": "All prompts are reviewed by the AI Engineer and Data Scientist before use. Prompt templates are documented in the project repository under /docs/prompt-log.txt and versioned accordingly."}, "output_1": {"status": "Yes", "remarks": "All AI-generated financial insights are reviewed and validated by the Subject Matter Expert (Dewi Rahayu) before being surfaced to end users. A validation checklist is applied to each output batch to check for hallucinations, bias, or inaccuracies."}, "output_2": {"status": "Yes", "remarks": "Any source code generated or assisted by Gen AI undergoes mandatory peer review by a senior developer, security static analysis scanning, and functional testing before integration into the customer analytics platform."}, "before_use_1": {"status": "Yes", "remarks": "The platform has been reviewed against OJK regulations, UU PDP No. 27/2022, and internal AI Ethics & Governance Policy. Legal and compliance sign-off obtained prior to project initiation."}, "before_use_2": {"status": "Yes", "remarks": "The generative AI platform used for financial insight generation is officially licensed and has received formal written approval from the Chief Technology Officer and Head of Digital Innovation."}, "before_use_3": {"status": "Yes", "remarks": "Platform settings have been configured to disable interaction history logging. The team has opted out of all model training data-sharing options provided by the Gen AI service provider."}, "utilization_1": {"status": "Yes", "remarks": "AI-generated insights and recommendations are only released after independent assessment and sign-off by the authorised SME. A review checklist is used to confirm outputs are ready for customer-facing use."}, "utilization_2": {"status": "Yes", "remarks": "A feedback and correction loop is in place. Inaccurate or inappropriate AI outputs are flagged, corrected, and logged in the incident register before any distribution to customers or stakeholders."}}, "sign_off": {"approved": "Yes", "prepared_by": "Ahmad Fauzi", "prepared_date": "2026-01-27", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "2026-01-27", "prepared_position": "Senior Delivery Manager", "prepared_signature": "data:image/png;base64,", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": "data:image/png;base64,"}}}	draft
ae5892cf-9769-4a96-8185-c2987d1809c7	5f8cf746-6035-447a-9cfa-3694bd423aaa	\N	\N	{"B_i": {"answer": "Yes", "remarks": "Dataset includes customer financial behaviour and transaction history, classified as sensitive personal financial data under UU PDP."}, "B_v": {"answer": "Yes", "remarks": "Customer consent for AI/ML model development is covered under the digital banking service agreement signed at account opening."}, "D_i": {"answer": "Yes", "remarks": "The credit risk scoring model utilises gradient boosting machine learning algorithms to predict default probability based on customer transaction patterns and financial behaviour data."}, "B_ii": {"answer": "Yes", "remarks": "Data is pseudonymized and aggregated prior to sharing. PII fields are masked and access is restricted to the authorized analytics team only."}, "B_iv": {"answer": "Yes", "remarks": "Written consent has been obtained through customer onboarding agreements and terms of service covering data use in credit risk assessment."}, "B_vi": {"answer": "Yes", "remarks": "All data processing is conducted within PT Finansial Nusantara's secured analytics environment with role-based access controls and audit logging."}, "A_i_1": {"answer": "No", "remarks": "Credit risk data is used for internal analytics only; no revenue cannibalization risk identified."}, "A_i_2": {"answer": "No", "remarks": "Data is pseudonymized before sharing; customer identity is protected throughout the process."}, "A_i_3": {"answer": "No", "remarks": "No other commercial interest risks have been identified for this data sharing request."}, "B_iii": {"answer": "Yes", "remarks": "Transaction records and credit history contain personal financial data subject to the Personal Data Protection Law (UU PDP No. 27/2022)."}, "C_i_1": {"answer": "No", "remarks": "OJK regulations on credit scoring and data sharing have been reviewed; this request complies with applicable banking sector regulations."}, "C_i_2": {"answer": "No", "remarks": "Data sharing is compliant with UU PDP No. 27 of 2022; appropriate technical and organisational safeguards are in place."}, "C_i_3": {"answer": "No", "remarks": "Internal data governance policy and data sharing SOP have been reviewed; this request is fully compliant with internal regulations."}, "A_ii_1": {"answer": "No", "remarks": "No highly confidential partnership information is included in the requested dataset."}, "A_ii_2": {"answer": "No", "remarks": "Dataset contains transactional and behavioural data only; no patent-related information involved."}, "A_ii_3": {"answer": "No", "remarks": "No merger or acquisition information is included in the scope of this data sharing."}, "A_ii_4": {"answer": "No", "remarks": "No other commercial secrets identified within the requested credit data dataset."}, "sign_off": {"remarks": "All data governance requirements have been reviewed and verified. This data sharing is approved for credit risk model development purposes only.", "approved": "Yes", "prepared_by": "Dian Pratiwi", "prepared_date": "", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "", "prepared_position": "Head of Analytics", "prepared_signature": "", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": ""}}	draft
